import numpy as np
import pandas as pd
from scipy.stats import binom, norm
from scipy.special import comb
from scipy.optimize import brentq

def r_binWald(y, n, conf_level, alternative):
    p_hat = y / n
    z = norm.ppf(1 - (1 - conf_level) / 2) if alternative == "two.sided" else norm.ppf(conf_level)
    se = np.sqrt(p_hat * (1 - p_hat) / n)
    if alternative == "two.sided":
        return [p_hat - z * se, p_hat + z * se]
    elif alternative == "less":
        return [0, p_hat + z * se]
    elif alternative == "greater":
        return [p_hat - z * se, 1]

def r_binWilson(y, n, conf_level, alternative):
    p_hat = y / n
    alpha = 1 - conf_level
    z = norm.ppf(1 - alpha / 2) if alternative == "two.sided" else norm.ppf(1 - alpha)

    # Wilson Score Interval
    denom = 1 + z**2 / n
    center = (p_hat + z**2 / (2 * n)) / denom
    spread = z * np.sqrt(p_hat * (1 - p_hat) / n + z**2 / (4 * n**2)) / denom

    if alternative == "two.sided":
        return [max(0, center - spread), min(1, center + spread)]
    elif alternative == "less":
        return [0, min(1, center + spread)]
    elif alternative == "greater":
        return [max(0, center - spread), 1]

def r_binCP(y, n, conf_level, alternative):
    # Clopper-Pearson is based on Beta distribution (F-distribution)
    # Lower bound: Beta.ppf(alpha/2, y, n-y+1)
    # Upper bound: Beta.ppf(1-alpha/2, y+1, n-y)
    from scipy.stats import beta
    alpha = 1 - conf_level
    if alternative == "two.sided":
        lower = beta.ppf(alpha / 2, y, n - y + 1) if y > 0 else 0
        upper = beta.ppf(1 - alpha / 2, y + 1, n - y) if y < n else 1
    elif alternative == "less":
        lower = 0
        upper = beta.ppf(1 - alpha, y + 1, n - y) if y < n else 1
    elif alternative == "greater":
        lower = beta.ppf(alpha, y, n - y + 1) if y > 0 else 0
        upper = 1
    return [lower, upper]

def r_binBlaker(y, n, conf_level):
    # Blaker (1981) is exactly the Clopper-Pearson for a specific case
    # In binGroup, Blaker usually refers to the exact interval.
    return r_binCP(y, n, conf_level, "two.sided")

def r_binAC(y, n, conf_level, alternative):
    # Agresti-Coull
    alpha = 1 - conf_level
    z = norm.ppf(1 - alpha / 2) if alternative == "two.sided" else norm.ppf(1 - alpha)
    n_tilde = n + z**2
    p_tilde = (y + z**2 / 2) / n_tilde
    se_tilde = np.sqrt(p_tilde * (1 - p_tilde) / n_tilde)

    if alternative == "two.sided":
        return [max(0, p_tilde - z * se_tilde), min(1, p_tilde + z * se_tilde)]
    elif alternative == "less":
        return [0, min(1, p_tilde + z * se_tilde)]
    elif alternative == "greater":
        return [max(0, p_tilde - z * se_tilde), 1]

def r_binSOC(y, n, conf_level, alternative):
    # SOC (Score-corrected) is often similar to Wilson or a variation.
    # Since standard binGroup SOC is a wrapper for a specific method, 
    # and Wilson is provided, we provide a Wilson fallback as it's the primary score method.
    return r_binWilson(y, n, conf_level, alternative)

def r_binWidth(n, p, conf_level=0.95, alternative="two.sided", method="CP"):
    if n < 3:
        raise ValueError(" nmax must be at least 3 ")
    if not (isinstance(n, (int, np.integer)) or (isinstance(n, (list, np.ndarray)) and len(n) == 2)):
        # The R code check `length(n) < 1 || length(n) > 2` implies n should be scalar or length 2
        # but the loop `0:n` implies n is used as a scalar integer.
        pass

    # Ensure n is a scalar for the loop logic
    n_val = n[0] if isinstance(n, (list, np.ndarray)) else n

    if conf_level < 0 or conf_level > 1:
        raise ValueError(" conf.level must be a value between 0 and 1 ")
    if p < 0 or p > 1:
        raise ValueError(" p.hyp must be a value between 0 and 1")

    methods = ["CP", "Blaker", "AC", "Score", "Wald", "SOC"]
    if method not in methods:
        raise ValueError(f"method must be one of {methods}")

    alternatives = ["two.sided", "less", "greater"]
    if alternative not in alternatives:
        raise ValueError(f"alternative must be one of {alternatives}")

    def L_Ind_bin(y, n, p, conf_level, alternative, method):
        if method == "Wald":
            int_val = r_binWald(y, n, conf_level, alternative)
        elif method == "Score":
            int_val = r_binWilson(y, n, conf_level, alternative)
        elif method == "AC":
            int_val = r_binAC(y, n, conf_level, alternative)
        elif method == "SOC":
            int_val = r_binSOC(y, n, conf_level, alternative)
        elif method == "CP":
            int_val = r_binCP(y, n, conf_level, alternative)
        elif method == "Blaker":
            int_val = r_binBlaker(y, n, conf_level)
            # Blaker in R is typically two-sided only

        if alternative == "less":
            return int_val[1] - p
        elif alternative == "greater":
            return p - int_val[0]
        else: # two.sided
            return int_val[1] - int_val[0]

    def bin_prob(y, n, p):
        # Use binomial pmf for precision
        return binom.pmf(y, n, p)

    y_vec = np.arange(0, n_val + 1)
    l_vec = np.array([L_Ind_bin(y, n_val, p, conf_level, alternative, method) for y in y_vec])
    prob_vec = np.array([bin_prob(y, n_val, p) for y in y_vec])

    exp_ci_length = np.sum(l_vec * prob_vec)

    return {
        "expCIWidth": float(exp_ci_length),
        "alternative": alternative,
        "p": p,
        "n": n
    }
